fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // For three points on a line, the meeting point minimizing total absolute distance
    // is any median of the points. With distinct values, it's the middle one after sorting.
    let mut a = [x1, x2, x3];
    a.sort();

    let median = a[1];
    let total = (a[0] - median).abs() + (a[2] - median).abs();

    total
}